import React from "react";

const ExportButtons = ({ exportAsJPEG, exportAsCSV }) => (
  <div className="flex justify-center space-x-4 mt-6 w-full">
    <button
      className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-50"
      onClick={exportAsJPEG}
    >
      Export as JPEG
    </button>
    <button
      className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-50"
      onClick={exportAsCSV}
    >
      Export Data as CSV
    </button>
  </div>
);

export default ExportButtons;