import React from 'react';

function AdminSettings() {
  // Enhanced design for better presentation
  return (
    <section className="admin-settings">
      <h2 className="admin-settings__title">Settings</h2>
      <p className="admin-settings__description">Configure various application settings here.</p>
      <form className="admin-settings__form">
        <div className="form-group">
          <label htmlFor="site_name">Site Name:</label>
          <input type="text" id="site_name" name="site_name" defaultValue="Your Website" />
        </div>
        <button className="btn btn-primary" type="submit">Save Settings</button>
      </form>
    </section>
  );
}

export default AdminSettings;