import React, { useState } from 'react';
import '../styles/Contact.css';

const phonenumber = "+251-912-345-678"; // Replace with your phone number

function Contact () {
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    message: ''
  });
  const [status, setStatus] = useState('');

  const handleChange = (e) => {
    const { id, value } = e.target;
    setFormData(prevState => ({
      ...prevState,
      [id]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setStatus('Sending...');

    try {
      const response = await fetch('http://localhost:3500/api/contact/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          first_name: formData.firstName,
          last_name: formData.lastName,
          email: formData.email,
          phone_number: formData.phone,
          message: formData.message,
        }),
      });

      const data = await response.json();

      if (response.ok) {
        setStatus('Message sent successfully! 😊');
        setFormData({
          firstName: '',
          lastName: '',
          email: '',
          phone: '',
          message: ''
        });
      } else {
        setStatus(`Failed to send message: ${data.message || 'Unknown error'}`);
        console.error('Submission error:', data);
      }
    } catch (error) {
      setStatus('Failed to send message. Please try again later.');
      console.error('Network error:', error);
    }
  };

  return (
    <div className="contact-container">
      <div className="content">
        <div className="info">
          <h1>Contact Us</h1>
          <p>Feel free to use the form or drop us an email. Old-fashioned phone calls work too.</p>
          <ul>
            <a href={`tel:${phonenumber}`} className="contact-link"> <li>{phonenumber}</li></a>
            <a className="contact-link" href='https://maps.app.goo.gl/Z3RVWMh8DkMSABHU8'><li>International Livestock Research Institute,<br />Addis Ababa</li></a>
          </ul>
        </div>
        <div className="form">
          <form onSubmit={handleSubmit}>
            <div className="name-fields">
              <div className="field">
                <label htmlFor="firstName">Name</label>
                <div className='FLname'>
                  <input type="text" id="firstName" placeholder="First" value={formData.firstName} onChange={handleChange} />
                </div>
              </div>
              <div className="field">
                <label htmlFor="lastName"> </label>
                <div className='FLname'>
                  <input type="text" id="lastName" placeholder="Last" value={formData.lastName} onChange={handleChange} />
                </div>
              </div>
            </div>
            <div className="field">
              <label htmlFor="email">Email</label>
              <input type="email" id="email" placeholder="example@email.com" value={formData.email} onChange={handleChange} />
            </div>
            <div className="field">
              <label htmlFor="phone">Phone (optional)</label>
              <input type="text" id="phone" placeholder="xxx-xxx-xxxx" value={formData.phone} onChange={handleChange} />
            </div>
            <div className="field">
              <label htmlFor="message">Message</label>
              <textarea id="message" placeholder="Type your message ..." value={formData.message} onChange={handleChange}></textarea>
            </div>
            <div className="submit">
              <button type="submit">Submit</button>
            </div>
            {status && <p className="status-message">{status}</p>}
          </form>
        </div>
      </div>
    </div>
  );
};

export default Contact;