import React, { useRef, useEffect, useState } from "react";
import { MapContainer, TileLayer, GeoJSON, LayersControl } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import "../../styles/Sliderpage.css"; // Make sure this CSS file is correctly linked
import captureMapImage from "./captureMapImage"; //  Make sure this file path is correct
import SuitabilityPopupHandler from "../Popups/suitabilityPopup"; // Make sure this file path is correct

const { BaseLayer } = LayersControl;

function SliderComponent({ geoJsonData, comparisonGeoJsonData, geoJsonKey }) {
  const [sliderValue, setSliderValue] = useState(100); // Start in the middle
  const [mapCenter] = useState([9.03, 38.74]);
  const [mapZoom] = useState(6);

  const topMapRef = useRef(null);
  const bottomMapRef = useRef(null);
  const [isDragging, setIsDragging] = useState(false); // Track slider dragging
  const syncing = useRef(false);

  // Suitability legend classes and colors
  const suitabilityClasses = {
    "Highly Suitable": "#008000",
    "Moderately Suitable": "#FFFF00",
    "Marginally Suitable": "#FFA500",
    "Not Suitable": "#FF0000",
  };
  const [activeSuitabilityClasses, setActiveSuitabilityClasses] = useState(
    Object.keys(suitabilityClasses).reduce((acc, className) => {
      acc[className] = true;
      return acc;
    }, {})
  );

  const getLayerStyle = (feature) => {
    const { suitability, type, soilClimate } = feature.properties;
    if (type === "suitability") {
      const styles = suitabilityClasses;
      const color = styles[suitability] || "#808080";
      if (!activeSuitabilityClasses[suitability]) {
        return { fillOpacity: 0, stroke: false };
      }
      return { color, fillColor: color, fillOpacity: 0.5 };
    } else if (type === "soilClimate") {
      const soilClimateColors = {
        soilpH: "#6A4C93",
        organicMatter: "#1982C4",
        rainfall: "#8AC926",
        temperature: "#FF595E",
        wind: "#FFCA3A",
        sunshine: "#FF924C",
      };
      const color = soilClimateColors[soilClimate] || "#808080";
      return { color, fillColor: color, fillOpacity: 0.5 };
    }
    return { color: "#808080", fillColor: "#808080", fillOpacity: 0.5 };
  };

  const onEachFeature = (feature, layer) => {
    SuitabilityPopupHandler({ feature, layer, getLayerStyle });
  };

  useEffect(() => {
    if (!topMapRef.current || !bottomMapRef.current) return;

    const topMap = topMapRef.current;
    const bottomMap = bottomMapRef.current;

    const syncMaps = (from, to) => {
      if (syncing.current) return;
      syncing.current = true;
      const center = from.getCenter();
      const zoom = from.getZoom();
      to.setView(center, zoom);
      setTimeout(() => (syncing.current = false), 100); // Short timeout
    };

    topMap.on("moveend zoomend", () => syncMaps(topMap, bottomMap));
    bottomMap.on("moveend zoomend", () => syncMaps(bottomMap, topMap));

    return () => {
      topMap.off("moveend zoomend");
      bottomMap.off("moveend zoomend");
    };
  }, []);

  const handleSliderMouseUp = () => {
    setIsDragging(false);
  };

  useEffect(() => {
    const handleMove = () => {
      if (isDragging && topMapRef.current && bottomMapRef.current) {
        const topMap = topMapRef.current;
        const bottomMap = bottomMapRef.current;
        // Sync the maps while dragging.  Use a timeout.
        if (!syncing.current) {
          syncing.current = true;
          const center = topMap.getCenter();
          const zoom = topMap.getZoom();
          bottomMap.setView(center, zoom);
          setTimeout(() => {
            syncing.current = false;
          }, 100);
        }
      }
    };
    window.addEventListener("mousemove", handleMove);
    window.addEventListener("mouseup", handleSliderMouseUp);

    return () => {
      window.removeEventListener("mousemove", handleMove);
      window.removeEventListener("mouseup", handleSliderMouseUp);
    };
  }, [isDragging]);

  // Legend click handler (same logic as Map.jsx)
  const handleLegendClick = (className, event) => {
    setActiveSuitabilityClasses((prevActiveClasses) => {
      const currentStatusOfClicked = prevActiveClasses[className];
      const activeCount = Object.values(prevActiveClasses).filter(Boolean).length;
      const totalClasses = Object.keys(suitabilityClasses).length;
      if (!event.shiftKey) {
        // Normal click: Always toggles just that class ON/OFF
        return {
          ...prevActiveClasses,
          [className]: !currentStatusOfClicked,
        };
      } else {
        // Shift+Click: smart behavior
        if (activeCount === totalClasses) {
          // All ON: isolate
          const newActiveClasses = {};
          Object.keys(suitabilityClasses).forEach((key) => {
            newActiveClasses[key] = key === className;
          });
          return newActiveClasses;
        } else if (activeCount === 1 && currentStatusOfClicked) {
          // Only one ON: reset all
          const newActiveClasses = {};
          Object.keys(suitabilityClasses).forEach((key) => {
            newActiveClasses[key] = true;
          });
          return newActiveClasses;
        } else {
          // Otherwise: toggle just that class
          return {
            ...prevActiveClasses,
            [className]: !currentStatusOfClicked,
          };
        }
      }
    });
  };

  // Pass filtered data to GeoJSON layers
  // For bottom map (comparison)
  const filteredComparisonGeoJsonData = comparisonGeoJsonData?.features?.length
    ? {
        ...comparisonGeoJsonData,
        features: comparisonGeoJsonData.features.filter((feature) =>
          feature.properties.type === "suitability"
            ? activeSuitabilityClasses[feature.properties.suitability]
            : true
        ),
      }
    : comparisonGeoJsonData;
  // For top map (main)
  const filteredGeoJsonData = geoJsonData?.features?.length
    ? {
        ...geoJsonData,
        features: geoJsonData.features.filter((feature) =>
          feature.properties.type === "suitability"
            ? activeSuitabilityClasses[feature.properties.suitability]
            : true
        ),
      }
    : geoJsonData;

  return (
    <div className="comparison-container suitability-map relative w-full h-full overflow-hidden">
      {/* Bottom Map (Full width) */}
      <div className="absolute top-0 left-0 w-full h-full z-0">
        <MapContainer
          center={mapCenter}
          zoom={mapZoom}
          className="w-full h-full"
          whenCreated={(map) => (bottomMapRef.current = map)}
        >
          <LayersControl position="topleft">
            <BaseLayer checked name="OpenStreetMap Bottom">
              <TileLayer
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                attribution="&copy; OpenStreetMap contributors"
              />
            </BaseLayer>
          </LayersControl>

          {filteredComparisonGeoJsonData?.features?.length > 0 && (
            <GeoJSON
              key={`comparison-${geoJsonKey}-${JSON.stringify(activeSuitabilityClasses)}`}
              data={filteredComparisonGeoJsonData}
              style={getLayerStyle}
              onEachFeature={onEachFeature}
            />
          )}
        </MapContainer>
      </div>

      {/* Top Map (slider-controlled width) */}
      <div
        className="absolute top-0 left-0 h-full z-10 overflow-hidden"
        style={{ width: `${sliderValue}%` }}
      >
        <MapContainer
          center={mapCenter}
          zoom={mapZoom}
          className="w-full h-full"
          whenCreated={(map) => (topMapRef.current = map)}
        >
          <LayersControl position="topleft">
            <BaseLayer checked name="OpenStreetMap Top">
              <TileLayer
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                attribution="&copy; OpenStreetMap contributors"
              />
            </BaseLayer>
          </LayersControl>

          {filteredGeoJsonData?.features?.length > 0 && (
            <GeoJSON
              key={`main-${geoJsonKey}-${JSON.stringify(activeSuitabilityClasses)}`}
              data={filteredGeoJsonData}
              style={getLayerStyle}
              onEachFeature={onEachFeature}
            />
          )}
        </MapContainer>
      </div>

      {/* Slider */}
      <input
        type="range"
        min="0"
        max="100"
        value={sliderValue}
        onChange={(e) => setSliderValue(parseInt(e.target.value))}
        className="slider absolute top-1/2 transform -translate-y-1/2 left-1 z-20 h-full opacity-50 cursor-ew-resize"
        style={{ writingMode: "bt-lr", WebkitAppearance: "slider-vertical" }} // Reduced width to avoid overlapping zoom controls
      />

      {/* Separator Line */}
      <div
        className="absolute top-0 h-full z-15 pointer-events-none" //  z-index to be above the maps
        style={{
          left: `calc(${sliderValue}% - 2px)`, // Adjust position if needed
          width: "4px", // Width of the line
          backgroundColor: "rgba(0, 0, 0, 0.5)", // black, slightly transparent
          boxShadow: "0 0 5px rgba(0,0,0,0.5)", // Subtle shadow
        }}
      />

      {/* Capture Button */}
      <button
        onClick={captureMapImage}
        className="absolute bottom-4 right-4 bg-blue-600 text-white px-4 py-2 rounded shadow-lg hover:bg-blue-700 z-30"
      >
        Capture Map
      </button>

      {/* Suitability Legend */}
      <div
        id="map-legend"
        className="absolute bottom-1 left-1 z-[1000] p-3 bg-white rounded-md shadow-md"
      >
        <div className="flex flex-col gap-2">
          <h4 className="text-gray-800 text-sm font-semibold mb-1">Suitability</h4>
          {Object.entries(suitabilityClasses).map(([className, color]) => (
            <div
              key={className}
              className={`flex items-center gap-2 cursor-pointer ${!activeSuitabilityClasses[className] ? 'line-through text-gray-400' : 'text-gray-700'}`}
              onClick={event => handleLegendClick(className, event)}
            >
              <div
                className="w-4 h-4 rounded-full border border-gray-300"
                style={{ backgroundColor: color }}
              ></div>
              <span className="text-sm">{className}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default SliderComponent;
