import React from 'react';
import { Link } from 'react-router-dom';
import AllianceLogo from '../../Assets/Logo/alliancelogo_cgiar_en.png'; // Import the image
import '../../styles/Footer.css';
import { NavLink } from 'react-router-dom';

const phonenumber = "+251-912-345-678"; // Replace with your phone number

function Footer() {
  return (
    <footer className="footer">
      <div className="footer-container">
        <div className="footer-section">
        <NavLink to="/">
                        <img
                            src={AllianceLogo}
                            alt="Alliance logo"
                            className="footer-logo h-12"
                        />
          </NavLink>
          <p>
            The Alliance of Bioversity International and CIAT is part of
            <a href="https://www.cgiar.org/" className="footer-link"> CGIAR</a>, a global research partnership for a food-secure future.
          </p>
        </div>
        <div className="footer-section">
          <Link to="/Contact"><h2 className="footer-title contact-footer-title">CONTACT</h2></Link>
          <p>Alliance Addis Ababa </p>
          <p>
            Address:
            <a href="https://maps.app.goo.gl/Z3RVWMh8DkMSABHU8" className="footer-link"> ILRI, Addis Ababa</a>
          </p>
          <p>
            Phone:
            <a href={`tel:${phonenumber}`} className="footer-link"> {phonenumber}</a>
          </p>
          <p>Fax: +12 34 56789</p>
        </div>
        <div className="footer-section">
          <h2 className="footer-title">LEGAL INFO</h2>
          <p>
            <a href="https://alliancebioversityciat.org/legal" className="footer-link">Our centers</a>
          </p>
          <p>
            <a href="https://alliancebioversityciat.org/privacy-policy" className="footer-link">Our Privacy Policy</a>
          </p>
        </div>
        <div className="footer-section">
          <h2 className="footer-title">FOLLOW</h2>
          <div className="footer-social">
            <div className="footer-social-item">
              <i className="fab fa-linkedin"></i>
              <a href="https://www.linkedin.com/company/bioversity-international/" className="footer-link"> Linkdin</a>
            </div>
            <div className="footer-social-item">
              <i className="fab fa-twitter"></i>
              <a href="https://x.com/BiovIntCIAT_eng" className="footer-link"> Twitter(X)</a>
            </div>
            <div className="footer-social-item">
              <i className="fab fa-facebook"></i>
              <a href="https://www.facebook.com/BiovIntCIAT.eng/" className="footer-link"> Facebook</a>
            </div>
            <div className="footer-social-item">
              <i className="fab fa-instagram"></i>
              <a href="https://www.instagram.com/bioversityciat/" className="footer-link"> Instagram</a>
            </div>
            <div className="footer-social-item">
              <i className="fab fa-youtube"></i>
              <a href="https://www.youtube.com/@bioversityciat" className="footer-link"> Youtube</a>
            </div>
          </div>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
