import React from 'react';
import CardComponent from './CardComponent';
function CardContainer(){
    return(
        <div className="home-card-container">
            <CardComponent title="Risk Map" text="Analyze potential farming risks like drought, pests, and extreme weather with an interactive heatmap. Understand threats before they impact your crops and plan accordingly." buttonLink="/risk-map"/>
            <CardComponent title="Diseases" text="Discover the best locations for growing wheat based on soil, weather, and climate data. Our suitability model identifies optimal regions for cultivation, ensuring higher yields and sustainable farming." buttonLink="/disease" />
            <CardComponent title="Advisory Reports" text="Get expert recommendations tailored to your region for better agricultural planning. Access research-backed insights to improve soil health, irrigation practices, and overall farm management." buttonLink="/advisory" />
        </div>
    );
}
export default CardContainer;