import React, { useEffect, useState } from "react";


function RiskSidebar({ riskTypes, setRiskTypes, filters, setFilters, riskData }) {
  const [dropdownData, setDropdownData] = useState({ regions: [], severities: [], crops: [] });

  useEffect(() => {
    const fetchDropdownData = async () => {
      try {
        const regionsResponse = await fetch("/api/regions");
        let regions = await regionsResponse.json();
        regions = regions.sort();

        const severitiesResponse = await fetch("/api/severity-levels");
        let severities = await severitiesResponse.json();
        const severityOrder = ["Low", "Moderate", "High", "Severe"];
        severities = severities.sort((a, b) => severityOrder.indexOf(a) - severityOrder.indexOf(b));

        // Get all unique crops from the full dummyRiskData, not just filtered data
        let crops = [];
        try {
          const allRiskData = await import("../../Data/dummyRiskData.json");
          crops = [...new Set(allRiskData.default.features.map(f => f.properties.crop))].filter(Boolean);
        } catch (e) {
          // fallback to riskData if import fails
          if (riskData && riskData.features) {
            crops = [...new Set(riskData.features.map(f => f.properties.crop))].filter(Boolean);
          }
        }

        setDropdownData({ regions, severities, crops });
      } catch (error) {
        console.error("Error fetching dropdown data:", error);
      }
    };

    fetchDropdownData();
  }, []); // Only run once on mount

  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilters((prev) => ({ ...prev, [name]: value }));
  };

  const exportToCSV = () => {
    if (!riskData || !riskData.features) {
      console.error("No risk data available to export.");
      return;
    }

    const csvRows = [["Region", "Severity", "Drought Impact", "Pests Present", "Soil Degradation Level", "Extreme Weather Risk"]];
    riskData.features.forEach(({ properties }) => {
      const row = [
        properties.region,
        properties.severity,
        properties.drought_impact ? "Yes" : "No",
        properties.pests_present ? "Yes" : "No",
        properties.soil_degradation_level,
        properties.extreme_weather_risk,
      ];
      csvRows.push(row);
    });

    const csvContent = csvRows.map(row => row.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "risk_data.csv";
    a.click();
    URL.revokeObjectURL(url);
  };
  

  return (
    <div className="bg-white border border-gray-300 p-3 w-[320px] rounded-md shadow-xl">
      <div className="shadow-md">
        <div className="flex justify-between items-center mb-2 p-3">
          <h2 className="text-lg font-semibold">FILTER PANEL</h2>
        </div>

        {/* Filter controls */}
        <div className="border border-gray-300 p-4 mb-4 rounded">
          <h3 className="text-md font-semibold mb-2">Risk Layers</h3>
          <div className="flex flex-col gap-2">
            {["drought", "pests", "soilDegradation", "extremeWeather"].map((riskKey) => (
              <label key={riskKey} className="flex items-center gap-2 capitalize">
                <input
                  type="checkbox"
                  checked={riskTypes[riskKey]}
                  onChange={() => setRiskTypes(prev => ({ ...prev, [riskKey]: !prev[riskKey] }))}
                />
                {riskKey.replace(/([A-Z])/g, " $1")}
              </label>
            ))}
          </div>
        </div>

        <div className="flex flex-col gap-4 mb-4">
          <select
            className="p-2 border border-gray-300 rounded"
            name="region"
            value={filters.region}
            onChange={handleFilterChange}
          >
            <option value="">All Regions</option>
            {dropdownData.regions.map((region) => (
              <option key={region} value={region}>
                {region}
              </option>
            ))}
          </select>

          {/* Crop filter dropdown */}
          <select
            className="p-2 border border-gray-300 rounded"
            name="crop"
            value={filters.crop || ""}
            onChange={handleFilterChange}
          >
            <option value="">All Crops</option>
            {dropdownData.crops.map((crop) => (
              <option key={crop} value={crop}>{crop}</option>
            ))}
          </select>

          <select
            className="p-2 border border-gray-300 rounded"
            name="severity"
            value={filters.severity}
            onChange={handleFilterChange}
          >
            <option value="">All Severities</option>
            {dropdownData.severities.map((severity) => (
              <option key={severity} value={severity}>
                {severity}
              </option>
            ))}
          </select>
        </div>

        <button
          onClick={exportToCSV}
          className="w-full bg-yellow-500 text-white py-2 rounded hover:bg-gray-700 transition mb-2" // Added mb-2 for spacing
        >
          Export to CSV
        </button>
      </div>
    </div>
  );
}

export default RiskSidebar;