import React, { useRef, useEffect, useState, useCallback } from "react";
import { MapContainer, TileLayer, LayersControl, GeoJSON, useMap, WMSTileLayer } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from 'leaflet';
import PrintControl from "./Printcontrol";

// Make sure these paths are correct for your project
import SuitabilityPopupHandler from "../Popups/suitabilityPopup";
import ethiostatedata from '../../Data/ethiostatesdata'; // Adjust the path as needed

// Helper function to find active WMS layers for the download modal
const getActiveWmsLayers = (map) => {
    const activeLayers = [];
    const layersControl = map.options.layersControl;
    if (!layersControl) return activeLayers;

    layersControl._layers.forEach(layerObj => {
        if (layerObj.overlay && map.hasLayer(layerObj.layer) && layerObj.layer.wmsParams) {
            activeLayers.push({
                name: layerObj.name,
                id: layerObj.layer.wmsParams.layers,
            });
        }
    });
    return activeLayers;
};

// Custom component to handle map interactions
function MapInteractions({ bounds, setMapInstance, layersControlRef }) {
    const map = useMap();

    useEffect(() => {
        setMapInstance(map);
        if (layersControlRef.current) {
            map.options.layersControl = layersControlRef.current;
        }
    }, [map, setMapInstance, layersControlRef]);

    useEffect(() => {
        if (bounds) {
            map.fitBounds(bounds, { padding: [50, 50] });
        }
    }, [map, bounds]);

    return null;
}


// --- MAIN MAP COMPONENT ---
function MapComponent({ geoJsonData, geoJsonKey, onFeatureClick }) {
    const mapRef = useRef(null);
    const layersControlRef = useRef(null);
    const [mapInstance, setMapInstance] = useState(null);
    const printControlRef = useRef(null);
    const downloadDropdownRef = useRef(null); // Ref for the download dropdown container

    const { BaseLayer } = LayersControl;
    const [initialZoom] = useState(() => (typeof window !== 'undefined' && window.innerWidth < 640 ? 5 : 6));

    // State for download dropdown visibility
    const [isDownloadDropdownOpen, setIsDownloadDropdownOpen] = useState(false);
    const [activeWmsForDownload, setActiveWmsForDownload] = useState([]); // To populate raster options
    const [selectedRaster, setSelectedRaster] = useState(''); // To track selected raster for WCS

    // Suitability Legend and Filtering state
    const suitabilityClasses = React.useMemo(() => ({
        "Highly Suitable": "#008000",
        "Moderately Suitable": "#FFFF00",
        "Marginally Suitable": "#FFA500",
        "Not Suitable": "#FF0000",
    }), []);
    const [activeSuitabilityClasses, setActiveSuitabilityClasses] = useState(
        Object.keys(suitabilityClasses).reduce((acc, className) => ({ ...acc, [className]: true }), {})
    );

    // Search Bar state
    const [searchTerm, setSearchTerm] = useState("");
    const [foundRegionBounds, setFoundRegionBounds] = useState(null);
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const [highlightedIndex, setHighlightedIndex] = useState(-1);

    // Memoized data
    const regionNames = React.useMemo(() => (ethiostatedata?.features || []).map(f => f.properties?.name).filter(Boolean), []);
    const filteredSuggestions = React.useMemo(() => {
        if (!searchTerm.trim()) return [];
        return regionNames.filter(name => name.toLowerCase().includes(searchTerm.toLowerCase()));
    }, [searchTerm, regionNames]);
    const filteredGeoJson = React.useMemo(() => {
        if (!geoJsonData || !geoJsonData.features) return null;
        return {
            ...geoJsonData,
            features: geoJsonData.features.filter((feature) => {
                if (feature.properties.type === "suitability") return activeSuitabilityClasses[feature.properties.suitability];
                return true;
            }),
        };
    }, [geoJsonData, activeSuitabilityClasses]);

    // Map Styling and Feature Interaction
    const getLayerStyle = (feature) => {
        if (feature.properties.type === "suitability") {
            const suitability = feature.properties.suitability;
            if (activeSuitabilityClasses[suitability]) {
                return { color: suitabilityClasses[suitability], fillColor: suitabilityClasses[suitability], fillOpacity: 0.5 };
            } else {
                return { fillOpacity: 0, stroke: false };
            }
        }
        return { color: "#808080", fillColor: "#808080", fillOpacity: 0.5 };
    };

    const onEachFeature = (feature, layer) => {
        SuitabilityPopupHandler({ feature, layer, getLayerStyle });
        layer.on({ click: () => onFeatureClick && onFeatureClick(feature) });
    };

    // Handler for Legend Clicks
    const handleLegendClick = useCallback((className, event) => {
        setActiveSuitabilityClasses(prev => {
            const currentStatus = prev[className];
            if (!event.shiftKey) return { ...prev, [className]: !currentStatus };
            const activeCount = Object.values(prev).filter(Boolean).length;
            const totalCount = Object.keys(prev).length;
            if (activeCount === totalCount) return Object.keys(suitabilityClasses).reduce((acc, key) => ({ ...acc, [key]: key === className }), {});
            if (activeCount === 1 && currentStatus) return Object.keys(suitabilityClasses).reduce((acc, key) => ({ ...acc, [key]: true }), {});
            return { ...prev, [className]: !currentStatus };
        });
    }, [suitabilityClasses]);

    // Handlers for Search
    const handleSearchChange = (event) => {
        setSearchTerm(event.target.value);
        setIsDropdownOpen(true);
        setHighlightedIndex(-1);
    };
    const handleSuggestionClick = (name) => {
        setSearchTerm(name);
        setIsDropdownOpen(false);
        setHighlightedIndex(-1);
        setTimeout(() => handleSearchSubmit(name), 0);
    };
    const handleSearchSubmit = useCallback((overrideName) => {
        const term = overrideName !== undefined ? overrideName : searchTerm;
        if (!term.trim()) return;
        const lowerCaseTerm = term.toLowerCase();
        const foundFeature = ethiostatedata.features.find(f => f.properties?.name?.toLowerCase().includes(lowerCaseTerm));
        if (foundFeature) {
            setFoundRegionBounds(L.geoJSON(foundFeature).getBounds());
        } else {
            alert("Region not found.");
        }
        setIsDropdownOpen(false);
    }, [searchTerm]);
    const handleKeyDown = (event) => {
        if (!isDropdownOpen || filteredSuggestions.length === 0) return;
        if (event.key === 'ArrowDown') {
            event.preventDefault();
            setHighlightedIndex(idx => Math.min(idx + 1, filteredSuggestions.length - 1));
        } else if (event.key === 'ArrowUp') {
            event.preventDefault();
            setHighlightedIndex(idx => Math.max(idx - 1, 0));
        } else if (event.key === 'Enter') {
            if (highlightedIndex >= 0) handleSuggestionClick(filteredSuggestions[highlightedIndex]);
            else handleSearchSubmit();
        } else if (event.key === 'Escape') {
            setIsDropdownOpen(false);
        }
    };

    // Download Handlers
    const handleDownloadClick = () => {
        // Toggle dropdown visibility
        setIsDownloadDropdownOpen(prev => !prev);
        // If opening, update active WMS layers for raster download
        if (!isDownloadDropdownOpen && mapInstance) {
            const activeLayers = getActiveWmsLayers(mapInstance);
            setActiveWmsForDownload(activeLayers);
            if (activeLayers.length > 0) {
                setSelectedRaster(activeLayers[0].id); // Pre-select first active raster
            }
        }
    };

    const handleDownloadMapImage = () => {
        if (mapInstance && mapInstance.easyPrintPlugin) {
            mapInstance.easyPrintPlugin.printMap('CurrentSize', 'map_capture');
        } else {
            alert('Map print plugin not ready. Please try again in a moment.');
        }
        setIsDownloadDropdownOpen(false); // Close dropdown after action
    };

    const handleDownloadRaster = () => {
        if (activeWmsForDownload.length === 0) {
            alert("No active raster layer found. Please enable a WMS overlay from the layers control.");
            setIsDownloadDropdownOpen(false);
            return;
        }

        // If there's only one raster, download it directly
        if (activeWmsForDownload.length === 1 && activeWmsForDownload[0].id === selectedRaster) {
            executeRasterDownload(selectedRaster);
            setIsDownloadDropdownOpen(false);
            return;
        }

        // For multiple rasters, we would need a sub-selection, but for now,
        // let's assume `selectedRaster` is always set from `activeWmsForDownload[0].id`
        // or a manual selection if you later add more UI to choose.
        if (selectedRaster) {
            executeRasterDownload(selectedRaster);
        } else {
            alert("Please select a raster layer to download.");
        }
        setIsDownloadDropdownOpen(false); // Close dropdown after action
    };

    const executeRasterDownload = (rasterId) => {
        if (!rasterId || !mapInstance) return;
        const bounds = mapInstance.getBounds();
        const geoserverUrl = "http://localhost:8080/geoserver/agroclim-suitability/wcs";
        const wcsParams = new URLSearchParams({
            service: 'WCS',
            version: '2.0.1',
            request: 'GetCoverage',
            CoverageID: rasterId,
            format: 'image/geotiff'
        });
        wcsParams.append('subset', `Long(${bounds.getWest()},${bounds.getEast()})`);
        wcsParams.append('subset', `Lat(${bounds.getSouth()},${bounds.getNorth()})`);
        window.open(`${geoserverUrl}?${wcsParams.toString()}`, '_blank');
    };

    // Effect to close dropdown on outside click
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (downloadDropdownRef.current && !downloadDropdownRef.current.contains(event.target)) {
                setIsDownloadDropdownOpen(false);
            }
        };

        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, [downloadDropdownRef]);

    // --- DYNAMIC WMS LAYERS ---
    const [wmsLayers, setWmsLayers] = useState([]);
    const [wmsLoading, setWmsLoading] = useState(true);
    const [wmsError, setWmsError] = useState(null);

    useEffect(() => {
        async function fetchWmsLayers() {
            setWmsLoading(true);
            setWmsError(null);
            try {
                const res = await fetch("http://localhost:3500/geoserver/geonode/wms?service=WMS&version=1.1.1&request=GetCapabilities");
                const text = await res.text();
                const parser = new window.DOMParser();
                const xml = parser.parseFromString(text, "text/xml");
                const rootLayer = xml.getElementsByTagName("Layer")[0];
                let wmsLayerList = [];
                if (rootLayer) {
                    const childLayers = Array.from(rootLayer.children).filter(child => child.tagName === "Layer");
                    wmsLayerList = childLayers
                        .filter(layer => layer.getElementsByTagName("Name")[0])
                        .map(layer => ({
                            name: layer.getElementsByTagName("Title")[0]?.textContent || layer.getElementsByTagName("Name")[0].textContent,
                            id: layer.getElementsByTagName("Name")[0].textContent
                        }));
                    console.log('All WMS layer IDs:', wmsLayerList.map(l => l.id));
                    // Exclude known demo/sample layers
                    const demoLayers = ["spearfish", "tasmania", "tiger-ny"];
                    wmsLayerList = wmsLayerList.filter(layer => !demoLayers.includes(layer.id));
                }
                setWmsLayers(wmsLayerList);
            } catch (err) {
                setWmsError("Failed to load WMS layers");
            } finally {
                setWmsLoading(false);
            }
        }
        fetchWmsLayers();
    }, []);

    // --- RENDER ---
    return (
            <MapContainer
                className="suitability-map w-full h-full rounded-lg border border-gray-300 z-0"
                center={[9.03, 38.74]}
                zoom={initialZoom}
                ref={mapRef}
            >
                <PrintControl ref={printControlRef} />
                <MapInteractions
                    bounds={foundRegionBounds}
                    setMapInstance={setMapInstance}
                    layersControlRef={layersControlRef}
                />
                <div className="leaflet-search-bar absolute top-4 left-1/2 -translate-x-1/2 z-[1000] w-[90%] md:w-2/3 lg:w-1/2 flex flex-col items-center">
                    <div className="w-full flex items-center bg-white rounded-full shadow-lg p-2 relative">
                        <input type="text" placeholder="Search by Region Name..." className="flex-grow p-2 pl-4 rounded-full focus:outline-none text-gray-700 text-sm" value={searchTerm} onChange={handleSearchChange} onKeyDown={handleKeyDown} onFocus={() => setIsDropdownOpen(true)} onBlur={() => setTimeout(() => setIsDropdownOpen(false), 200)} autoComplete="off" />
                        <button onClick={() => handleSearchSubmit()} className="p-2 text-gray-600 hover:text-gray-900 focus:outline-none" aria-label="Search">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                        </button>
                        {isDropdownOpen && filteredSuggestions.length > 0 && (
                            <ul className="absolute left-0 top-full mt-1 w-full bg-white border border-gray-200 rounded-md shadow-lg z-50 max-h-48 overflow-y-auto">
                                {filteredSuggestions.map((name, idx) => (
                                    <li key={name} className={`px-4 py-2 cursor-pointer hover:bg-blue-100 ${idx === highlightedIndex ? 'bg-blue-100' : ''}`} onMouseDown={() => handleSuggestionClick(name)}>{name}</li>
                                ))}
                            </ul>
                        )}
                    </div>
                </div>
                <LayersControl position="topleft" ref={layersControlRef}>
                    <BaseLayer checked name="OpenStreetMap">
                        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors' />
                    </BaseLayer>
                    {/* Dynamically render WMS overlays */}
                    {wmsLoading && <div className="p-2 text-xs text-gray-500">Loading WMS layers...</div>}
                    {wmsError && <div className="p-2 text-xs text-red-500">{wmsError}</div>}
                    {wmsLayers.map(layer => (
                        <LayersControl.Overlay key={layer.id} name={layer.name}>
                            <WMSTileLayer url="http://localhost:3500/geoserver/geonode/wms" layers={layer.id} format="image/png" transparent={true} />
                        </LayersControl.Overlay>
                    ))}
                    <LayersControl.Overlay name="Ethiopian States">
                        <GeoJSON data={ethiostatedata} style={{ color: "#000000", weight: 1, opacity: 1 }} interactive={false} />
                    </LayersControl.Overlay>
                </LayersControl>
                {filteredGeoJson && filteredGeoJson.features.length > 0 && (
                    <GeoJSON key={`filtered-${geoJsonKey}-${JSON.stringify(activeSuitabilityClasses)}`} data={filteredGeoJson} style={getLayerStyle} onEachFeature={onEachFeature} />
                )}
                <div id="map-legend" className="absolute bottom-12 sm:bottom-1 left-1 z-[1000] p-3 bg-white bg-opacity-90 rounded-md shadow-md">
                    <div className="flex flex-col gap-2">
                        <h4 className="text-gray-800 text-sm font-semibold mb-1">Suitability</h4>
                        {Object.entries(suitabilityClasses).map(([className, color]) => (
                            <div key={className} className={`flex items-center gap-2 cursor-pointer ${!activeSuitabilityClasses[className] ? 'line-through text-gray-400' : 'text-gray-700'}`} onClick={(event) => handleLegendClick(className, event)}>
                                <div className="w-4 h-4 rounded-full border border-gray-300" style={{ backgroundColor: color }}></div>
                                <span className="text-sm">{className}</span>
                            </div>
                        ))}
                    </div>
                </div>
                <div className="leaflet-control-container">
                    <div className="leaflet-bottom leaflet-right">
                        {/* Download Button with Dropdown */}
                        <div ref={downloadDropdownRef} className="relative leaflet-control bg-white rounded-lg shadow-md mb-2 mr-2">
                            <button
                                onClick={handleDownloadClick}
                                className="w-auto px-4 py-2 flex items-center justify-center gap-2 text-white bg-blue-600 rounded-lg hover:bg-blue-700 transition-colors duration-200 ease-in-out focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-50"
                                title="Download Options"
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                    <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
                                </svg>
                                <span className="mr-1">Download</span>
                                <svg xmlns="http://www.w3.org/2000/svg" className={`h-4 w-4 transform transition-transform ${isDownloadDropdownOpen ? 'rotate-180' : ''}`} viewBox="0 0 20 20" fill="currentColor">
                                    <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                                </svg>
                            </button>

                            {isDownloadDropdownOpen && (
                                <div className="absolute bottom-full right-0 mb-2 w-48 bg-white rounded-lg shadow-xl py-2 z-[2000] ring-1 ring-black ring-opacity-5 focus:outline-none">
                                    <div className="py-1">
                                        <button
                                            onClick={handleDownloadMapImage}
                                            className="block px-4 py-2 text-sm text-gray-700 w-full text-left hover:bg-gray-100"
                                        >
                                            JPG (Map Image)
                                        </button>
                                        <button
                                            onClick={handleDownloadRaster}
                                            className="block px-4 py-2 text-sm text-gray-700 w-full text-left hover:bg-gray-100"
                                        >
                                            Raster (.geotiff)
                                        </button>
                                        {/* You could add more options here if needed, e.g., for vector data */}
                                        {/* {activeWmsForDownload.length > 1 && ( // Example of showing sub-options if multiple rasters
                                            <div className="border-t border-gray-200 mt-2 pt-2">
                                                <p className="px-4 text-xs text-gray-500">Select Raster:</p>
                                                <select value={selectedRaster} onChange={(e) => setSelectedRaster(e.target.value)} className="w-full px-4 py-2 text-sm text-gray-700 focus:outline-none">
                                                    {activeWmsForDownload.map(layer => <option key={layer.id} value={layer.id}>{layer.name}</option>)}
                                                </select>
                                                <button onClick={() => executeRasterDownload(selectedRaster)} className="block px-4 py-2 text-sm text-blue-600 w-full text-left hover:bg-blue-50">Download Selected</button>
                                            </div>
                                        )} */}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </MapContainer>

    );
}

export default MapComponent;