// src/components/Data-Display/RiskMapComponent.jsx

import React, { useRef, useEffect, useState, useCallback } from "react";
import { MapContainer, TileLayer, LayersControl, GeoJSON, useMap, WMSTileLayer } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from 'leaflet'; // Import Leaflet for advanced map interactions
import PrintControl from "./Printcontrol"; // Ensure this path is correct for your project

import ethiostatedata from '../../Data/ethiostatesdata.json'; // Ethiopian state boundaries for search/overlay

// Helper function to find active WMS layers for the download modal
const getActiveWmsLayers = (map) => {
    const activeLayers = [];
    if (map && map._layers) {
        Object.values(map._layers).forEach(layer => {
            if (layer instanceof L.TileLayer.WMS && map.hasLayer(layer)) {
                if (layer.options && layer.options.layers) {
                    activeLayers.push({
                        name: layer.options.name || layer.options.layers, // Use name from options or layer ID
                        id: layer.options.layers,
                    });
                }
            }
        });
    }
    // Also check LayersControl's internal state for robustness
    // This part requires access to the layersControl instance or its internal _layers
    // For simplicity, we assume map.options.layersControl might be set in MapInteractions,
    // or rely on the direct layer iteration above.
    return activeLayers;
};

// Component to handle map interactions like setting map instance and fitting bounds
function MapInteractions({ setMapInstance, layersControlRef, foundRegionBounds }) {
    const map = useMap();

    useEffect(() => {
        setMapInstance(map); // Pass map instance up to the parent component (or directly used in this component)
        if (layersControlRef.current) {
            // Store LayersControl instance if needed for external access (e.g., in getActiveWmsLayers)
            map.options.layersControl = layersControlRef.current;
        }
    }, [map, setMapInstance, layersControlRef]);

    useEffect(() => {
        if (foundRegionBounds) {
            map.flyToBounds(foundRegionBounds, { maxZoom: 9, duration: 1.2 });
        }
    }, [map, foundRegionBounds]);

    return null;
}


function RiskMapComponent({ geoJsonData, geoJsonKey, onFeatureClick, riskTypes, setRiskTypes }) {
    const mapRef = useRef(null);
    const layersControlRef = useRef(null); // Ref for LayersControl
    const [mapInstance, setMapInstance] = useState(null); // State to hold the Leaflet map instance

    // Download dropdown state
    const [isDownloadDropdownOpen, setIsDownloadDropdownOpen] = useState(false);
    const downloadDropdownRef = useRef(null);
    const [activeWmsForDownload, setActiveWmsForDownload] = useState([]);
    const [selectedRaster, setSelectedRaster] = useState('');

    // WMS Layers State
    const [wmsLayers, setWmsLayers] = useState([]);
    const [wmsLoading, setWmsLoading] = useState(true);
    const [wmsError, setWmsError] = useState(null);

    // Search bar states
    const [searchTerm, setSearchTerm] = useState("");
    const [foundRegionBounds, setFoundRegionBounds] = useState(null);
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const [highlightedIndex, setHighlightedIndex] = useState(-1);

    // Initial zoom based on screen size
    const initialZoom = window.innerWidth < 640 ? 5 : 6;

    // Severity color mapping
    const getSeverityColor = useCallback((severity) => {
        switch (severity) {
            case "Low": return "#008000"; // Green
            case "Moderate": return "#FFFF00"; // Yellow
            case "High": return "#FFA500"; // Orange
            case "Severe": return "#FF0000"; // Red
            default: return "gray";
        }
    }, []);

    // Style for dummy GeoJSON data
    const geoJsonStyle = useCallback((feature) => {
        const color = getSeverityColor(feature.properties.severity);
        return {
            color: color,
            fillColor: color,
            fillOpacity: 0.5,
            weight: 3,
            opacity: 0.9,
        };
    }, [getSeverityColor]);

    // OnEachFeature for dummy GeoJSON interaction
    const onEachFeature = useCallback((feature, layer) => {
        if (feature.properties) {
            const popupContent = `
                <strong>Region:</strong> ${feature.properties.region}<br>
                <strong>Severity:</strong> ${feature.properties.severity}<br>
                <strong>Drought Impact:</strong> ${feature.properties.drought_impact || 'N/A'}<br>
                <strong>Pests Present:</strong> ${feature.properties.pests_present || 'N/A'}<br>
                <strong>Soil Degradation Level:</strong> ${feature.properties.soil_degradation_level || 'N/A'}<br>
                <strong>Extreme Weather Risk:</strong> ${feature.properties.extreme_weather_risk || 'N/A'}
            `;
            layer.on("mouseover", () => {
                layer.bindPopup(popupContent).openPopup();
                layer.setStyle({ weight: 3, opacity: 1 });
            });
            layer.on("mouseout", () => {
                layer.closePopup();
                layer.setStyle(geoJsonStyle(feature)); // Revert to initial style
            });
            layer.on("click", () => onFeatureClick(feature)); // Pass click to parent
        }
    }, [geoJsonStyle, onFeatureClick]);


    // Fetch WMS layers from GeoServer
    useEffect(() => {
        async function fetchWmsLayers() {
            setWmsLoading(true);
            setWmsError(null);
            try {
                const res = await fetch("http://localhost:8080/geoserver/agroclim-risk/wms?service=WMS&version=1.1.1&request=GetCapabilities");
                const text = await res.text();
                const parser = new window.DOMParser();
                const xml = parser.parseFromString(text, "text/xml");
                const rootLayer = xml.getElementsByTagName("Layer")[0];
                let wmsLayerList = [];
                if (rootLayer) {
                    const childLayers = Array.from(rootLayer.children).filter(child => child.tagName === "Layer");
                    wmsLayerList = childLayers
                        .filter(layer => layer.getElementsByTagName("Name")[0])
                        .map(layer => ({
                            name: layer.getElementsByTagName("Title")[0]?.textContent || layer.getElementsByTagName("Name")[0].textContent,
                            id: layer.getElementsByTagName("Name")[0].textContent
                        }));
                    // Filter out known demo/sample layers or layers not relevant
                    const layersToExclude = ["spearfish", "tasmania", "tiger-ny", "soilpH", "organicMatter", "rainfall", "temperature", "wind", "sunshine", "Highly Suitable", "Moderately Suitable", "Marginally Suitable", "Not Suitable"];
                    wmsLayerList = wmsLayerList.filter(layer => !layersToExclude.includes(layer.id));
                }
                setWmsLayers(wmsLayerList);
            } catch (err) {
                console.error("Error fetching WMS layers:", err);
                setWmsError("Failed to load WMS layers. Make sure GeoServer is running and accessible at http://localhost:8080.");
            } finally {
                setWmsLoading(false);
            }
        }
        fetchWmsLayers();
    }, []);

    // --- Download Handlers ---
    const handleDownloadClick = () => {
        setIsDownloadDropdownOpen(prev => !prev);
        if (!isDownloadDropdownOpen && mapInstance) {
            const activeLayers = getActiveWmsLayers(mapInstance);
            setActiveWmsForDownload(activeLayers);
            if (activeLayers.length > 0) {
                setSelectedRaster(activeLayers[0].id);
            }
        }
    };

    const handleDownloadMapImage = () => {
        if (mapInstance && mapInstance.easyPrintPlugin) {
            mapInstance.easyPrintPlugin.printMap('CurrentSize', 'risk_map_capture');
        } else {
            alert('Map print plugin not ready. Please try again in a moment.');
        }
        setIsDownloadDropdownOpen(false);
    };

    const handleDownloadRaster = () => {
        if (activeWmsForDownload.length === 0) {
            alert("No active raster layer found. Please enable a WMS overlay from the layers control to download.");
            setIsDownloadDropdownOpen(false);
            return;
        }
        if (selectedRaster) {
            executeRasterDownload(selectedRaster);
        } else {
            alert("Please select a raster layer to download.");
        }
        setIsDownloadDropdownOpen(false);
    };

    const executeRasterDownload = (rasterId) => {
        if (!rasterId || !mapInstance) return;
        const bounds = mapInstance.getBounds();
        const geoserverUrl = "http://localhost:8080/geoserver/agroclim-risk/wcs";
        const wcsParams = new URLSearchParams({
            service: 'WCS',
            version: '2.0.1',
            request: 'GetCoverage',
            CoverageID: rasterId,
            format: 'image/geotiff'
        });
        wcsParams.append('subset', `Long(${bounds.getWest()},${bounds.getEast()})`);
        wcsParams.append('subset', `Lat(${bounds.getSouth()},${bounds.getNorth()})`);
        window.open(`${geoserverUrl}?${wcsParams.toString()}`, '_blank');
    };

    const handleDownloadDummyGeoJSON = () => {
        if (!geoJsonData || geoJsonData.features.length === 0) {
            alert("No dummy risk data visible to download.");
            setIsDownloadDropdownOpen(false);
            return;
        }

        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(geoJsonData));
        const downloadAnchorNode = document.createElement('a');
        downloadAnchorNode.setAttribute("href", dataStr);
        downloadAnchorNode.setAttribute("download", "ethiopia_filtered_risk_data.geojson");
        document.body.appendChild(downloadAnchorNode);
        downloadAnchorNode.click();
        downloadAnchorNode.remove();
        setIsDownloadDropdownOpen(false);
    };

    // Effect to close download dropdown on outside click
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (downloadDropdownRef.current && !downloadDropdownRef.current.contains(event.target)) {
                setIsDownloadDropdownOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, []);

    // --- SEARCH BAR LOGIC ---
    const regionNames = React.useMemo(() => (ethiostatedata.features || []).map(f => f.properties?.name).filter(Boolean), []);
    const filteredSuggestions = React.useMemo(() => {
        if (!searchTerm.trim()) return [];
        return regionNames.filter(name => name.toLowerCase().includes(searchTerm.toLowerCase()));
    }, [searchTerm, regionNames]);

    const handleSearchChange = (event) => {
        setSearchTerm(event.target.value);
        setIsDropdownOpen(true);
        setHighlightedIndex(-1);
    };
    const handleSuggestionClick = (name) => {
        setSearchTerm(name);
        setIsDropdownOpen(false);
        setHighlightedIndex(-1);
        setTimeout(() => handleSearchSubmit(name), 0);
    };
    const handleSearchSubmit = useCallback((overrideName) => {
        const term = overrideName !== undefined ? overrideName : searchTerm;
        if (!term.trim()) return;
        const lowerCaseTerm = term.toLowerCase();
        const foundFeature = ethiostatedata.features.find(f => f.properties?.name?.toLowerCase().includes(lowerCaseTerm));
        if (foundFeature && mapInstance) {
            const bounds = L.geoJSON(foundFeature.geometry).getBounds();
            if (bounds.isValid()) {
                setFoundRegionBounds(bounds); // Trigger MapInteractions to fly to bounds
            } else {
                console.warn("Invalid bounds for feature:", foundFeature);
                alert("Region found, but map could not zoom to it (invalid geometry).");
            }
        } else {
            alert("Region not found in Ethiopian States data.");
        }
        setIsDropdownOpen(false);
    }, [searchTerm, mapInstance]);

    const handleKeyDown = (event) => {
        if (!isDropdownOpen || filteredSuggestions.length === 0) return;
        if (event.key === 'ArrowDown') {
            event.preventDefault();
            setHighlightedIndex(prev => Math.min(prev + 1, filteredSuggestions.length - 1));
        } else if (event.key === 'ArrowUp') {
            event.preventDefault();
            setHighlightedIndex(prev => Math.max(prev - 1, 0));
        } else if (event.key === 'Enter') {
            if (highlightedIndex >= 0) handleSuggestionClick(filteredSuggestions[highlightedIndex]);
            else handleSearchSubmit();
        } else if (event.key === 'Escape') {
            setIsDropdownOpen(false);
        }
    };


    return (
        <MapContainer
            className="Risk-map h-full w-full rounded-md"
            center={[9.03, 38.74]}
            zoom={initialZoom}
            ref={mapRef}
        >
            <PrintControl />
            <MapInteractions
                setMapInstance={setMapInstance}
                layersControlRef={layersControlRef}
                foundRegionBounds={foundRegionBounds}
            />

            {/* SEARCH BAR */}
            <div className="leaflet-search-bar absolute top-4 left-1/2 -translate-x-1/2 z-[1000] w-[90%] md:w-2/3 lg:w-1/2 flex flex-col items-center">
                <div className="w-full flex items-center bg-white rounded-full shadow-lg p-2 relative">
                    <input type="text" placeholder="Search by Region Name..." className="flex-grow p-2 pl-4 rounded-full focus:outline-none text-gray-700 text-sm" value={searchTerm} onChange={handleSearchChange} onKeyDown={handleKeyDown} onFocus={() => setIsDropdownOpen(true)} onBlur={() => setTimeout(() => setIsDropdownOpen(false), 200)} autoComplete="off" />
                    <button onClick={() => handleSearchSubmit()} className="p-2 text-gray-600 hover:text-gray-900 focus:outline-none" aria-label="Search">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                    </button>
                    {isDropdownOpen && filteredSuggestions.length > 0 && (
                        <ul className="absolute left-0 top-full mt-1 w-full bg-white border border-gray-200 rounded-md shadow-lg z-50 max-h-48 overflow-y-auto">
                            {filteredSuggestions.map((name, idx) => (
                                <li key={name} className={`px-4 py-2 cursor-pointer hover:bg-blue-100 ${idx === highlightedIndex ? 'bg-blue-100' : ''}`} onMouseDown={() => handleSuggestionClick(name)}>{name}</li>
                            ))}
                        </ul>
                    )}
                </div>
            </div>

            <LayersControl position="topleft" ref={layersControlRef}>
                <LayersControl.BaseLayer checked name="OpenStreetMap">
                    <TileLayer
                        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                        attribution="&copy; <a href='https://www.openstreetmap.org/copyright'>OpenStreetMap</a> contributors"
                    />
                </LayersControl.BaseLayer>
                <LayersControl.Overlay name="Ethiopian Regions">
                    <GeoJSON
                        data={ethiostatedata}
                        style={{ color: "#000000", weight: 1, opacity: 1, fill: false }}
                        interactive={false}
                    />
                </LayersControl.Overlay>

                {/* Dynamically added WMS Layers from GeoServer */}
                {wmsLoading && <LayersControl.Overlay name="Loading WMS..." disabled><div className="p-2 text-xs text-gray-500">Loading GeoServer layers...</div></LayersControl.Overlay>}
                {wmsError && <LayersControl.Overlay name="WMS Error" disabled><div className="p-2 text-xs text-red-500">{wmsError}</div></LayersControl.Overlay>}
                {wmsLayers.map(layer => (
                    <LayersControl.Overlay key={layer.id} name={layer.name}>
                        <WMSTileLayer
                            url="http://localhost:8080/geoserver/agroclim-risk/wms"
                            layers={layer.id}
                            format="image/png"
                            transparent={true}
                            name={layer.name} // Pass name for getActiveWmsLayers
                        />
                    </LayersControl.Overlay>
                ))}
            </LayersControl>

            {/* Dummy GeoJSON Layer (filtered by parent) */}
            {geoJsonData && geoJsonData.features && geoJsonData.features.length > 0 && (
                <GeoJSON
                    key={`risk-data-${geoJsonKey}`} // Use key to force re-render on new data
                    data={geoJsonData}
                    style={geoJsonStyle}
                    onEachFeature={onEachFeature}
                />
            )}

            {/* Legend for Severity Levels */}
            <div className="map-legend absolute bottom-4 left-4 bg-white bg-opacity-90 p-3 rounded-md shadow-md z-[1000]">
                <div className="legend-section">
                    <h4 className="font-semibold mb-2 text-gray-800 text-sm">Severity</h4>
                    {["Low", "Moderate", "High", "Severe"].map(severity => (
                        <div key={severity} className="legend-item flex items-center gap-2 mb-1">
                            <div className="w-4 h-4 rounded-full border border-gray-300" style={{ backgroundColor: getSeverityColor(severity) }}></div>
                            <span className="text-sm text-gray-700">{severity}</span>
                        </div>
                    ))}
                </div>
            </div>

            {/* Download button with dropdown */}
            <div className="absolute bottom-6 right-6 z-[1100] flex flex-col items-end pointer-events-auto download-btn-container">
                <div ref={downloadDropdownRef} className="relative">
                    <button
                        onClick={handleDownloadClick}
                        className="w-auto px-4 py-2 flex items-center justify-center gap-2 text-white bg-blue-600 rounded-md shadow-md hover:bg-blue-700 transition-colors duration-200 ease-in-out focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-50"
                        title="Download Options"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                            <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
                        </svg>
                        <span className="mr-1">Download</span>
                        <svg xmlns="http://www.w3.org/2000/svg" className={`h-4 w-4 transform transition-transform ${isDownloadDropdownOpen ? 'rotate-180' : ''}`} viewBox="0 0 20 20" fill="currentColor">
                            <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                        </svg>
                    </button>

                    {isDownloadDropdownOpen && (
                        <div className="absolute bottom-full right-0 mb-2 w-48 bg-white rounded-lg shadow-xl py-2 z-[2000] ring-1 ring-black ring-opacity-5 focus:outline-none">
                            <div className="py-1">
                                <button
                                    onClick={handleDownloadMapImage}
                                    className="block px-4 py-2 text-sm text-gray-700 w-full text-left hover:bg-gray-100"
                                >
                                    JPG (Map Image)
                                </button>
                                <div className="border-t border-gray-200 my-1"></div>
                                <p className="px-4 py-2 text-xs text-gray-500">GeoServer Rasters:</p>
                                {activeWmsForDownload.length > 0 ? (
                                    <>
                                        <select
                                            className="block w-full px-4 py-2 text-sm text-gray-700 bg-gray-50 border border-gray-300 rounded-md mb-2 focus:outline-none focus:ring focus:border-blue-300"
                                            value={selectedRaster}
                                            onChange={(e) => setSelectedRaster(e.target.value)}
                                        >
                                            {activeWmsForDownload.map(layer => (
                                                <option key={layer.id} value={layer.id}>{layer.name}</option>
                                            ))}
                                        </select>
                                        <button
                                            onClick={handleDownloadRaster}
                                            className="block px-4 py-2 text-sm text-blue-600 w-full text-left hover:bg-blue-50 hover:text-blue-700"
                                        >
                                            Download Selected Raster (.geotiff)
                                        </button>
                                    </>
                                ) : (
                                    <p className="px-4 py-2 text-xs text-gray-500 italic">No active WMS layers.</p>
                                )}
                                <div className="border-t border-gray-200 my-1"></div>
                                <button
                                    onClick={handleDownloadDummyGeoJSON}
                                    className="block px-4 py-2 text-sm text-gray-700 w-full text-left hover:bg-gray-100"
                                >
                                    Vector (Visible Dummy GeoJSON)
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </MapContainer>
    );
}

export default RiskMapComponent;