import React, { useEffect, useState } from "react";
import SideBar from "../components/UI/SuitabilitySidebar";
import MapComponent from "../components/Data-Display/Map";
import MapHeader from "../components/Data-Display/MapHeader";
import CardContainer from "../components/Data-Display/CardContainer";
import "../styles/home.css";

function HomeSuitabilityMap() {
    const [isSidebarOpen, setIsSidebarOpen] = useState(() => {
        // Check screen size on initial render
        return window.innerWidth > 768; // Open sidebar if screen width is greater than 768px
    });

    const [geoJsonKey, setGeoJsonKey] = useState(0);
    const [suitabilityLayers, setSuitabilityLayers] = useState({
        "Highly Suitable": true,
        "Moderately Suitable": true,
        "Marginally Suitable": true,
        "Not Suitable": true,
    });
    const [soilClimateLayers, setSoilClimateLayers] = useState({
        soilpH: false,
        organicMatter: false,
        rainfall: false,
        temperature: false,
        wind: false,
        sunshine: false,
    });
    const [geoJsonData, setGeoJsonData] = useState({ type: "FeatureCollection", features: [] });
    const [filters, setFilters] = useState({
        scenario: "",
        timeframe: "",
        season: "",
    });

    const toggleSidebar = () => {
        setIsSidebarOpen(!isSidebarOpen);
    };

    useEffect(() => {
        const fetchData = async () => {
            try {
                const [suitabilityResponse, soilClimateResponse] = await Promise.all([
                    fetch("/api/suitability-data"),
                    fetch("/api/soilclimate-data"),
                ]);
                const suitabilityData = await suitabilityResponse.json();
                const soilClimateData = await soilClimateResponse.json();
                const allFeatures = [...suitabilityData.features, ...soilClimateData.features];
                const newFilteredFeatures = allFeatures.filter((feature) => {
                    const matchesScenario = !filters.scenario || feature.properties.scenario === filters.scenario;
                    const matchesTimeframe = !filters.timeframe || feature.properties.timeframe === filters.timeframe;
                    const matchesSeason = !filters.season || feature.properties.season === filters.season;
                    if (feature.properties.type === "suitability") {
                        return (
                            suitabilityLayers[feature.properties.suitability] &&
                            matchesScenario &&
                            matchesTimeframe &&
                            matchesSeason
                        );
                    } else if (feature.properties.type === "soilClimate") {
                        return (
                            soilClimateLayers[feature.properties.soilClimate] &&
                            matchesScenario &&
                            matchesTimeframe &&
                            matchesSeason
                        );
                    }
                    return false;
                });
                setGeoJsonData({ type: "FeatureCollection", features: newFilteredFeatures });
                setGeoJsonKey((prevKey) => prevKey + 1);
            } catch (error) {
                console.error("Error fetching data:", error);
            }
        };
        fetchData();
    }, [suitabilityLayers, soilClimateLayers, filters]);

    return (
        <div className="home-suitability-page">
            <h1 className="home-text-header font-bold text-3xl">Wheat Suitability Map</h1>
            <MapHeader/>
            <div className="home-map-sidebar">
                <div className="home-map-container">
                    <MapComponent geoJsonData={geoJsonData} geoJsonKey={geoJsonKey} />
                </div>
                <div className="absolute top-4 right-4 z-[2001]">
                        <button
                            className="map-burger-menu text-xl cursor-pointer bg-white bg-opacity-90 rounded-full p-2 shadow-md hover:bg-gray-100"
                            style={{ boxShadow: '0 2px 8px rgba(0,0,0,0.15)' }}
                            onClick={toggleSidebar}
                        >
                            <i className="fas fa-filter"></i>
                        </button>
                    </div>
                <div className={`home-sidebar-container ${isSidebarOpen ? "open" : "hidden"}`}>
                    <SideBar
                        suitabilityLayers={suitabilityLayers}
                        setSuitabilityLayers={setSuitabilityLayers}
                        soilClimateLayers={soilClimateLayers}
                        setSoilClimateLayers={setSoilClimateLayers}
                        filters={filters}
                        setFilters={setFilters}
                        geoJsonData={geoJsonData}
                    />
                </div>
            </div>
            <CardContainer />
        </div>
    );
}

export default HomeSuitabilityMap;





