import React, { useState } from "react";
import { Line } from "react-chartjs-2";
import ExportButtons from "./ExportButtons";
import html2canvas from "html2canvas";

const BiomassTrendSection = ({ biomassTrendData, biomassTrendOptions }) => {
  // Range state: [start, end]
  const [range, setRange] = useState([0, biomassTrendData.labels.length - 1]);
  const [, setDragging] = useState(null); // 'start' or 'end' or null

  const handleRangeChange = (type, value) => {
    let [start, end] = range;
    value = Number(value);
    if (type ===  'start') {
      start = Math.min(value, end - 1);
    } else {
      end = Math.max(value, start + 1);
    }
    setRange([start, end]);
  };

  // Slice data for chart
  const slicedLabels = biomassTrendData.labels.slice(range[0], range[1] + 1);
  const slicedData = biomassTrendData.datasets[0].data.slice(range[0], range[1] + 1);
  const chartData = {
    ...biomassTrendData,
    labels: slicedLabels,
    datasets: [
      {
        ...biomassTrendData.datasets[0],
        data: slicedData,
      },
    ],
  };

  // Export chart as JPEG
  const exportAsJPEG = async () => {
    const chartDiv = document.getElementById("biomass-trend-chart");
    if (!chartDiv) return;
    const canvas = await html2canvas(chartDiv);
    const link = document.createElement("a");
    link.download = "biomass_trend_chart.jpg";
    link.href = canvas.toDataURL("image/jpeg", 0.95);
    link.click();
  };

  // Export sliced data as CSV
  const exportAsCSV = () => {
    let csv = "Label,Value\n";
    for (let i = 0; i < slicedLabels.length; i++) {
      csv += `"${slicedLabels[i]}",${slicedData[i]}\n`;
    }
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "biomass_trend_data.csv";
    link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <section className="w-full mt-6 flex flex-col items-center">
      <div className="w-full max-w-full">
        <div className="w-full relative mb-4">
          <div className="flex flex-col md:flex-row md:justify-between text-xs text-gray-500 mb-1 px-1 gap-1">
            <span>Start: <b>{biomassTrendData.labels[range[0]]}</b></span>
            <span>End: <b>{biomassTrendData.labels[range[1]]}</b></span>
          </div>
          <div className="flex items-center gap-2">
            <input
              type="range"
              min="0"
              max={biomassTrendData.labels.length - 2}
              value={range[0]}
              onChange={e => handleRangeChange('start', e.target.value)}
              onMouseDown={() => setDragging('start')}
              onMouseUp={() => setDragging(null)}
              className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer range-sm"
              aria-label="Select start of date range"
            />
            <input
              type="range"
              min="1"
              max={biomassTrendData.labels.length - 1}
              value={range[1]}
              onChange={e => handleRangeChange('end', e.target.value)}
              onMouseDown={() => setDragging('end')}
              onMouseUp={() => setDragging(null)}
              className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer range-sm"
              aria-label="Select end of date range"
            />
          </div>
          <div className="flex justify-between text-xs text-gray-500 mt-1 px-1">
            <span>{biomassTrendData.labels[0]}</span>
            <span>{biomassTrendData.labels[biomassTrendData.labels.length - 1]}</span>
          </div>
        </div>
        <div className="border border-gray-300 rounded p-4 h-[350px] md:h-[400px]" id="biomass-trend-chart">
          <Line data={chartData} options={biomassTrendOptions} />
        </div>
      </div>
      <ExportButtons exportAsJPEG={exportAsJPEG} exportAsCSV={exportAsCSV} />
    </section>
  );
};

export default BiomassTrendSection;