import React from "react";
import { Line } from "react-chartjs-2";
import ExportButtons from "./ExportButtons";
import html2canvas from "html2canvas";

const BiomassForecastSection = ({ biomassForecastData, biomassForecastOptions }) => {
  // Export chart as JPEG
  const exportAsJPEG = async () => {
    const chartDiv = document.getElementById("biomass-forecast-chart");
    if (!chartDiv) return;
    const canvas = await html2canvas(chartDiv);
    const link = document.createElement("a");
    link.download = "biomass_forecast_chart.jpg";
    link.href = canvas.toDataURL("image/jpeg", 0.95);
    link.click();
  };

  // Export chart data as CSV
  const exportAsCSV = () => {
    let csv = "Label,Value\n";
    const labels = biomassForecastData.labels;
    const data = biomassForecastData.datasets[0].data;
    for (let i = 0; i < labels.length; i++) {
      csv += `"${labels[i]}",${data[i]}\n`;
    }
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "biomass_forecast_data.csv";
    link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <section className="w-full mt-6 flex flex-col items-center">
      <div className="w-full max-w-full">
        <div className="border border-gray-300 rounded p-4 h-[350px] md:h-[400px]" id="biomass-forecast-chart">
          <Line data={biomassForecastData} options={biomassForecastOptions} />
        </div>
      </div>
      <ExportButtons exportAsJPEG={exportAsJPEG} exportAsCSV={exportAsCSV} />
    </section>
  );
};

export default BiomassForecastSection;