import React from 'react';

function AdvisoryUpload() {
  const handleAdvisorySubmit = (event) => {
    event.preventDefault();
    const formData = new FormData(event.target);
    // In the future, you'll send this formData to your backend API
    console.log('Advisory Form Data:', Object.fromEntries(formData));
    alert('Advisory data submitted (frontend only)'); // Placeholder
  };

  // Enhanced design for better presentation
  return (
    <section className="advisory-upload">
      <h2 className="advisory-upload__title">Upload New Advisory</h2>
      <form className="advisory-upload__form" onSubmit={handleAdvisorySubmit}>
        <div className="form-group">
          <label htmlFor="title">Title:</label>
          <input type="text" id="title" name="title" required />
        </div>
        <div className="form-group">
          <label htmlFor="publication_date">Date Posted:</label>
          <input type="date" id="publication_date" name="publication_date" />
        </div>
        <div className="form-group">
          <label htmlFor="category">Category:</label>
          <select id="category" name="category">
            <option value="seasonal">Seasonal</option>
            <option value="monthly">Monthly</option>
          </select>
        </div>
        <div className="form-group">
          <label htmlFor="advisory_content">Advisory Content:</label>
          <textarea id="advisory_content" name="advisory_content" rows="10" required></textarea>
        </div>
        <div className="form-group">
          <label htmlFor="rainfall_forecast">Rainfall Forecast:</label>
          <input type="text" id="rainfall_forecast" name="rainfall_forecast" />
        </div>
        <div className="form-group">
          <label htmlFor="temperature_outlook">Temperature Outlook:</label>
          <input type="text" id="temperature_outlook" name="temperature_outlook" />
        </div>
        <div className="form-group">
          <label htmlFor="potential_risks">Potential Risks:</label>
          <input type="text" id="potential_risks" name="potential_risks" />
        </div>
        <div className="form-group">
          <label htmlFor="recommendation">Recommendation:</label>
          <textarea id="recommendation" name="recommendation" rows="5"></textarea>
        </div>
        <div className="form-group">
          <label htmlFor="featured_image">Featured Image/File:</label>
          <input type="file" id="featured_image" name="featured_image" />
        </div>
        <button className="btn btn-primary" type="submit">Save Advisory</button>
      </form>
    </section>
  );
}

export default AdvisoryUpload;