import React, { useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faTimes } from '@fortawesome/free-solid-svg-icons';
import RegionInfoSection from './RegionInfoSection';
import BiomassTrendSection from './BiomassTrendSection';
import BiomassForecastSection from './BiomassForecastSection';
import { getPolygonBounds } from './geoUtils';
import L from 'leaflet';
import markerIcon2x from 'leaflet/dist/images/marker-icon-2x.png';
import markerIcon from 'leaflet/dist/images/marker-icon.png';
import markerShadow from 'leaflet/dist/images/marker-shadow.png';
import '../../styles/SuitabilityDetailPopup.css';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
);



delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: markerIcon2x,
  iconUrl: markerIcon,
  shadowUrl: markerShadow,
});


function SuitabilityDetailPopup({ feature, onClose }) {
  const [activeTab, setActiveTab] = useState('Region Info');
  if (!feature) return null;
  const { properties, geometry } = feature;
  const regionName = properties.region || 'Unknown Region';

  // Map center/bounds logic
  let mapCenter = [9.03, 38.74];
  let bounds = undefined;
  if (geometry && geometry.type === 'Point' && Array.isArray(geometry.coordinates)) {
    mapCenter = [geometry.coordinates[1], geometry.coordinates[0]];
  } else if (
    (geometry && geometry.type === 'Polygon' && Array.isArray(geometry.coordinates) && geometry.coordinates.length > 0 && geometry.coordinates[0].length > 0) ||
    (geometry && geometry.type === 'MultiPolygon' && Array.isArray(geometry.coordinates) && geometry.coordinates.length > 0 && geometry.coordinates[0][0].length > 0)
  ) {
    bounds = getPolygonBounds(geometry);
    if (bounds && bounds.length > 0) {
      mapCenter = bounds[0];
    }
  }
  const zoomLevel = 7;
// Dummy data for Biomass Trend graph based on image_527d98.png
  const biomassTrendData = {
    labels: [
      '2022-01-01', '2022-02-18', '2022-04-07', '2022-05-25', '2022-07-12', '2022-08-29',
      '2022-10-16', '2022-12-03', '2023-01-17', '2023-03-06', '2023-04-23', '2023-06-10',
      '2023-07-28', '2023-09-14', '2023-11-01', '2023-12-19', '2024-02-02', '2024-03-21',
      '2024-05-08', '2024-06-25', '2024-08-12', '2024-09-29', '2024-11-16', '2025-01-01',
      '2025-02-18', '2025-04-07'
    ],
    datasets: [
      {
        label: 'Biomass (t/ha)',
        data: [
          0.0, 0.1, 0.3, 0.5, 1.0, 1.9, 0.8, 0.5, 0.4, 1.6, 1.3, 0.9, 0.7, 0.6, 0.3, 0.1,
          0.0, 0.0, 1.0, 0.1, 2.2, 0.8, 0.0, 0.0, 0.0, 0.0
        ],
        fill: false,
        borderColor: '#4FB0AE',
        tension: 0.1,
        pointRadius: 3,
        pointBackgroundColor: '#4FB0AE',
        pointBorderColor: '#fff',
        pointHoverRadius: 5,
        pointHoverBackgroundColor: '#4FB0AE',
        pointHoverBorderColor: '#fff',
      },
    ],
  };

  const biomassTrendOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: false,
      },
      title: {
        display: true,
        text: `Biomass Trend ${regionName}`,
        font: {
          size: 14,
          weight: 'normal'
        },
        color: '#333'
      },
      tooltip: {
        mode: 'index',
        intersect: false,
      },
    },
    scales: {
      x: {
        title: {
          display: true,
          text: 'Date',
          font: { size: 12 },
          color: '#555'
        },
        ticks: {
          autoSkip: true,
          maxTicksLimit: 10,
          color: '#555'
        },
        grid: {
          display: false
        }
      },
      y: {
        title: {
          display: true,
          text: 'Biomass (t/ha)',
          font: { size: 12 },
          color: '#555'
        },
        min: 0,
        max: 2.5,
        ticks: {
          stepSize: 0.5,
          color: '#555'
        },
        grid: {
          color: '#eee'
        }
      },
    },
  };

  // Dummy data for Biomass Forecast graph based on image_528cbf.png
  const biomassForecastData = {
    labels: [
      '2025-05-09', '2025-05-25', '2025-06-10', '2025-06-26'
    ],
    datasets: [
      {
        label: 'Biomass (t/ha)',
        data: [0.00, 0.03, 0.08, 0.15],
        fill: false,
        borderColor: '#4FB0AE',
        tension: 0.4,
        pointRadius: 3,
        pointBackgroundColor: '#4FB0AE',
        pointBorderColor: '#fff',
        pointHoverRadius: 5,
        pointHoverBackgroundColor: '#4FB0AE',
        pointHoverBorderColor: '#fff',
      },
    ],
  };

  const biomassForecastOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: false,
      },
      title: {
        display: true,
        text: `Biomass Forecast ${regionName}`,
        font: {
          size: 14,
          weight: 'normal'
        },
        color: '#333'
      },
      tooltip: {
        mode: 'index',
        intersect: false,
      },
    },
    scales: {
      x: {
        title: {
          display: true,
          text: 'Date',
          font: { size: 12 },
          color: '#555'
        },
        ticks: {
          autoSkip: false,
          maxRotation: 0,
          minRotation: 0,
          color: '#555'
        },
        grid: {
          display: false
        }
      },
      y: {
        title: {
          display: true,
          text: 'Biomass (t/ha)',
          font: { size: 12 },
          color: '#555'
        },
        min: 0,
        max: 0.16,
        ticks: {
          stepSize: 0.02,
          color: '#555'
        },
        grid: {
          color: '#eee'
        }
      },
    },
  };

  // Export logic (can be moved to a hook or utility)
  const exportAsJPEG = async () => { /* ...existing code... */ };
  const exportAsCSV = () => { /* ...existing code... */ };

  return (
    <div className="w-fit max-w-full mx-auto p-4 bg-white text-gray-900 font-sans overflow-y-auto">
      <header className="flex items-center justify-between border-b border-gray-300 pb-3 mb-4">
        <h1 className="text-lg font-normal">Region Detail: {regionName}</h1>
        <button
          aria-label="Close"
          className="text-gray-500 hover:text-gray-700 focus:outline-none"
          onClick={onClose}
        >
          <FontAwesomeIcon icon={faTimes} className="text-lg" />
        </button>
      </header>
      <nav className="flex space-x-6 border-b border-gray-300 mb-4">
        <button
          aria-current={activeTab === 'Region Info'}
          className={`font-semibold text-gray-900 hover:text-gray-700 px-3 py-1 focus:outline-none ${
            activeTab === 'Region Info'
              ? 'text-blue-600 border border-blue-200 rounded -mb-px'
              : ''
          }`}
          type="button"
          onClick={() => setActiveTab('Region Info')}
        >
          Region Info
        </button>
        <button
          className={`font-semibold text-gray-900 hover:text-gray-700 px-3 py-1 focus:outline-none ${
            activeTab === 'Biomass Trend'
              ? 'text-blue-600 border border-blue-200 rounded -mb-px'
              : ''
          }`}
          type="button"
          onClick={() => setActiveTab('Biomass Trend')}
        >
          Biomass Trend
        </button>
        <button
          className={`font-semibold text-gray-900 hover:text-gray-700 px-3 py-1 focus:outline-none ${
            activeTab === 'Biomass Forecast'
              ? 'text-blue-600 border border-blue-200 rounded -mb-px'
              : ''
          }`}
          type="button"
          onClick={() => setActiveTab('Biomass Forecast')}
        >
          Biomass Forecast
        </button>
      </nav>
      <main>
        {activeTab === 'Region Info' && (
          <RegionInfoSection
            regionName={regionName}
            properties={properties}
            geometry={geometry}
            bounds={bounds}
            mapCenter={mapCenter}
            zoomLevel={zoomLevel}
          />
        )}
        {activeTab === 'Biomass Trend' && (
          <BiomassTrendSection
            biomassTrendData={biomassTrendData}
            biomassTrendOptions={biomassTrendOptions}
            exportAsJPEG={exportAsJPEG}
            exportAsCSV={exportAsCSV}
          />
        )}
        {activeTab === 'Biomass Forecast' && (
          <BiomassForecastSection
            biomassForecastData={biomassForecastData}
            biomassForecastOptions={biomassForecastOptions}
            exportAsJPEG={exportAsJPEG}
            exportAsCSV={exportAsCSV}
          />
        )}
      </main>
    </div>
  );
}

export default SuitabilityDetailPopup;