import React, { useState } from 'react';
import { NavLink } from 'react-router-dom';
import '../../styles/Navbar.css';
import AllianceLogo from '../../Assets/Logo/alliancelogo_cgiar_en.png';

function Navbar() {
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);

    const toggleSidebar = () => {
        setIsSidebarOpen(!isSidebarOpen);
    };

    const closeSidebar = () => {
        setIsSidebarOpen(false);
    };

    return (
        <nav className="navbar">
            <div className="nav-container flex items-center justify-between">
                <div className="flex items-center space-x-4">
                    <NavLink to="/">
                        <img
                            src={AllianceLogo}
                            alt="Alliance logo"
                            className="h-12"
                        />
                    </NavLink>
                </div>
                <button
                    className="hamburger-menu text-white text-2xl md:hidden"
                    onClick={toggleSidebar}
                >
                    ☰
                </button>
                <div className={`sidebar ${isSidebarOpen ? 'open' : ''}`}>
                    <button className="close-sidebar" onClick={closeSidebar}>
                        ✖
                    </button>
                    <ul className="sidebar-links">
                        <li>
                            <NavLink
                                to="/suitability-map"
                                className={({ isActive }) =>
                                    isActive ? 'link active-link' : 'link hover:text-gray-300'
                                }
                                onClick={closeSidebar}
                            >
                                SUITABILITY MAP
                            </NavLink>
                        </li>
                        <li>
                            <NavLink
                                to="/risk-map"
                                className={({ isActive }) =>
                                    isActive ? 'link active-link' : 'link hover:text-gray-300'
                                }
                                onClick={closeSidebar}
                            >
                                RISK MAP
                            </NavLink>
                        </li>
                        <li>
                            <NavLink
                                to="/advisory"
                                className={({ isActive }) =>
                                    isActive ? 'link active-link' : 'link hover:text-gray-300'
                                }
                                onClick={closeSidebar}
                            >
                                ADVISORY
                            </NavLink>
                        </li>
                        <li>
                            <NavLink
                                to="/disease"
                                className={({ isActive }) =>
                                    isActive ? 'link active-link' : 'link hover:text-gray-300'
                                }
                                onClick={closeSidebar}
                            >
                                DISEASE
                            </NavLink>
                        </li>
                        <li>
                            <NavLink
                                to="/about"
                                className={({ isActive }) =>
                                    isActive ? 'link active-link' : 'link hover:text-gray-300'
                                }
                                onClick={closeSidebar}
                            >
                                ABOUT US
                            </NavLink>
                        </li>
                    </ul>
                </div>
                <ul className="nav-links hidden md:flex space-x-6 text-white text-sm font-semibold">
                    <li>
                        <NavLink
                            to="/suitability-map"
                            className={({ isActive }) =>
                                isActive ? 'link active-link' : 'link hover:text-gray-300'
                            }
                        >
                            SUITABILITY MAP
                        </NavLink>
                    </li>
                    <li>
                        <NavLink
                            to="/risk-map"
                            className={({ isActive }) =>
                                isActive ? 'link active-link' : 'link hover:text-gray-300'
                            }
                        >
                            RISK MAP
                        </NavLink>
                    </li>
                    <li>
                        <NavLink
                            to="/advisory"
                            className={({ isActive }) =>
                                isActive ? 'link active-link' : 'link hover:text-gray-300'
                            }
                        >
                            ADVISORY
                        </NavLink>
                    </li>
                    <li>
                        <NavLink
                            to="/disease"
                            className={({ isActive }) =>
                                isActive ? 'link active-link' : 'link hover:text-gray-300'
                            }
                        >
                            DISEASE
                        </NavLink>
                    </li>
                    <li>
                        <NavLink
                            to="/about"
                            className={({ isActive }) =>
                                isActive ? 'link active-link' : 'link hover:text-gray-300'
                            }
                        >
                            ABOUT US
                        </NavLink>
                    </li>
                </ul>
            </div>
        </nav>
    );
}

export default Navbar;