import html2canvas from "html2canvas";

const captureMapImage = () => {
        const mapElement = document.querySelector(".suitability-map"); // Ensure this selector is correct
        if (!mapElement) {
          alert("Map element not found!");
          return;
        }
    
        // Add a class to the map element temporarily to potentially adjust styles for capture
        mapElement.classList.add("capturing-map");
    
        html2canvas(mapElement, {
          useCORS: true, // Important for loading tiles from different domains
          // You might need to adjust these based on your map's size and rendering
          width: mapElement.offsetWidth,
          height: mapElement.offsetHeight,
          // scale: window.devicePixelRatio, // May improve resolution, but can be slow
        }).then((canvas) => {
          // Remove the temporary class
          mapElement.classList.remove("capturing-map");
    
          const link = document.createElement("a");
          link.download = "suitability_map_capture.png";
          link.href = canvas.toDataURL("image/png");
          link.click();
        }).catch((error) => {
          console.error("Error capturing map:", error);
          alert("Failed to capture map. See console for details.");
          mapElement.classList.remove("capturing-map"); // Ensure class is removed on error
        });
      };

  export default captureMapImage;
