// File: /src/components/Data-Display/FeaturePopupHandler.jsx

const SuitabilityPopupHandler = ({ feature, layer, getLayerStyle }) => {
    const handleMouseOver = () => {
        let popupContent = "";

        if (feature.properties.type === "suitability") {
            popupContent = `<strong>Suitability:</strong> ${feature.properties.suitability}`;
            if (feature.properties.suitability) {
                popupContent += `<br><strong>Region:</strong> ${feature.properties.region}`
                    + `<br><strong>Scenario:</strong> ${feature.properties.scenario}`
                    + `<br><strong>Season:</strong> ${feature.properties.season}`
                    + `<br><strong>Timeframe:</strong> ${feature.properties.timeframe}`
                    + `<br><strong>Crop:</strong> ${feature.properties.crop}`
                    + `<br><strong>Description:</strong> ${feature.properties.description}`;
            }
        } else if (feature.properties.type === "soilClimate") {
            popupContent = `<strong>Soil Climate Factor:</strong> ${feature.properties.soilClimate}`;
            const { soilClimate } = feature.properties;

            if (soilClimate === "organicMatter" || soilClimate === "soilpH" || soilClimate === "wind" ||
                soilClimate === "temperature" || soilClimate === "sunshine" || soilClimate === "rainfall") {
                popupContent += `<br><strong>Region:</strong> ${feature.properties.region}`
                    + `<br><strong>Scenario:</strong> ${feature.properties.scenario}`
                    + `<br><strong>Season:</strong> ${feature.properties.season}`
                    + `<br><strong>Timeframe:</strong> ${feature.properties.timeframe}`;
            }

            if (soilClimate === "soilpH") {
                popupContent += `<br><strong>pH Value:</strong> ${feature.properties.pH_value}`;
            }
            if (soilClimate === "wind") {
                popupContent += `<br><strong>Wind Speed:</strong> ${feature.properties.wind_speed}`;
            }
            if (soilClimate === "temperature") {
                popupContent += `<br><strong>Temperature:</strong> ${feature.properties.temperature}`;
            }
            if (soilClimate === "sunshine") {
                popupContent += `<br><strong>UV index:</strong> ${feature.properties.uv_index}`;
            }
            if (soilClimate === "rainfall") {
                popupContent += `<br><strong>Rainfall:</strong> ${feature.properties.rainfall_value_mm}`;
            }

            popupContent += `</br><strong>Description:</strong> ${feature.properties.description}`;
        }

        layer.bindPopup(popupContent).openPopup();
        layer.setStyle({ weight: 3, opacity: 1 });
    };

    const handleMouseOut = () => {
        layer.closePopup();
        layer.setStyle(getLayerStyle(feature));
    };

    layer.on("mouseover", handleMouseOver);
    layer.on("mouseout", handleMouseOut);

    return null; // This component doesn't render anything
};

export default SuitabilityPopupHandler;
